NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Zechariah'

CHAPTERS = {
    1: {
        1: 'Im achten Monat, im zweiten Jahr des Darius, geschah das Wort Jehovahs an Sacharjah, den Sohn Berechjahs, des Sohnes Iddos, den Propheten, und Er sprach:',
        2: 'Jehovah war sehr entrüstet über eure Väter.',
        3: 'Du aber sprich zu ihnen: So spricht Jehovah der Heerscharen: Kehret zurück zu Mir, spricht Jehovah der Heerscharen, dann kehre Ich zurück zu euch, spricht Jehovah der Heerscharen.',
        4: 'Seid nicht wie eure Väter, denen die ersten Propheten zuriefen und sprachen: So spricht Jehovah der Heerscharen: Kehret doch zurück von euren bösen Wegen und euren bösen Werken, aber sie hörten nicht und merkten nicht auf Mich, spricht Jehovah.',
        5: 'Wo sind nun eure Väter? Und die Propheten, leben sie ewig?',
        6: 'Doch Meine Worte und Meine Satzungen, die Ich Meinen Knechten, den Propheten, hatte geboten, erreichten sie eure Väter nicht? Und sie kehrten zurück und sprachen: Wie Jehovah der Herrscharen gesonnen uns zu tun nach unseren Wegen und nach unseren Werken, so hat Er mit uns getan.',
        7: 'Am vierundzwanzigsten Tage des elften Monats, welcher ist der Monat Schebat, im zweiten Jahr des Darius, geschah das Wort Jehovahs an Sacharjah, den Sohn Berechjahus, des Sohnes Iddos, an den Propheten, und Er sprach:',
        8: 'Ich sah in der Nacht, und siehe, ein Mann ritt auf einem roten Pferd, und er stand zwischen den Myrten, die in der Tiefe sind, und hinter ihm rote, braune und weiße Pferde.',
        9: 'Und ich sprach: Was sind diese, mein Herr? Und der Engel, der mit redete, sprach zu mir: Ich will dich sehen lassen, was diese sind.',
        10: 'Und es hub an der Mann, der zwischen den Myrten stand, und sprach: Diese sind es, die Jehovah sandte, durch das Land zu ziehen.',
        11: 'Und sie antworteten dem Engel des Jehovah, der zwischen den Myrten stand, und sprachen: Wir sind durch das Land gezogen, und siehe, das Land wird bewohnt und rastet.',
        12: 'Und es antwortete der Engel Jehovahs und sprach: Jehovah der Heerscharen, wie lange willst Du Dich nicht erbarmen Jerusalems und der Städte Jehudahs, gegen die Du diese siebzig Jahre ergrimmt bist?',
        13: 'Und es antwortete Jehovah dem Engel, der mit mir redete, gute Worte, tröstliche Worte;',
        14: 'Und zu mir sprach der Engel, der mit mir redete: Rufe und sprich: So spricht Jehovah der Heerscharen: Ich eifere mit großem Eifer für Jerusalem und für Zijon.',
        15: 'Und Ich bin entrüstet mit großer Entrüstung wider die sorglosen Völkerschaften, indem Ich ein wenig entrüstet war, und sie zum Übel beistanden.',
        16: 'Darum, so spricht Jehovah, kehre Ich zurück mit Erbarmen zu Jerusalem: Mein Haus, spricht Jehovah der Heerscharen, soll in ihm aufgebaut und die Meßschnur über Jerusalem ausgespannt werden.',
        17: 'Noch rufe und sprich: So spricht Jehovah der Heerscharen: Noch werden sich Meine Städte ausbreiten wegen des Guten, und Jehovah tröstet noch Zijon, und erwählt noch Jerusalem.',
    },
    2: {
        1: 'Und ich hob meine Augen auf und sah, und siehe: vier Hörner.',
        2: 'Und ich sprach zu dem Engel, der mit mir redete: Was sind diese? Und er sprach zu mir: Dies sind die Hörner, die Jehudah, Israel und Jerusalem zersprengten.',
        3: 'Und Jehovah ließ mich vier Werkleute sehen.',
        4: 'Und ich sprach: Was sind diese gekommen zu tun? Und Er sprach, sprechend: Dies sind die Hörner, die Jehudah zersprengten, dermaßen, daß kein Mann das Haupt erhob. Und diese sind gekommen, diese aufzuscheuchen, niederzuwerfen die Hörner der Völkerschaften, die das Horn erhoben wider das Land Jehudah, um es zu zersprengen.',
        5: 'Und ich hob meine Augen auf und sah, und siehe, da war ein Mann und eine Schnur zum Messen war in seiner Hand.',
        6: 'Und ich sprach: Wohin gehst du? Und er sprach zu mir: Jerusalem zu messen, um zu sehen, was seine Breite und was seine Länge sei.',
        7: 'Und siehe, der Engel, der mit mir redete, ging hinaus, und ein anderer Engel kam heraus ihm entgegen.',
        8: 'Und er sprach zu ihm: Laufe, rede mit diesem Jüngling, sprechend: Als offen Land soll Jerusalem bewohnt werden ob der Menge von Mensch und Vieh in seiner Mitte.',
        9: 'Und Ich will, spricht Jehovah, ihm eine Mauer von Feuer ringsum sein und ihm zur Herrlichkeit sein in seiner Mitte.',
        10: 'Auf, auf! und fliehet aus dem Lande der Mitternacht! spricht Jehovah, denn wie die vier Winde der Himmel breite Ich euch aus, spricht Jehovah.',
        11: 'Auf Zijon, entrinne, die du bei Babels Tochter hast gewohnt.',
        12: 'Denn so spricht Jehovah der Heerscharen, nach der Verherrlichung hat Er mich zu den Völkerschaften gesandt, die euch ausgebeutet hatten; denn wer euch anrührt, der rührt Seinen Augapfel an.',
        13: 'Denn siehe, Ich schwenke Meine Hand wider sie, daß sie zur Beute werden denen, die ihnen gedient, auf daß ihr erkennt, daß Jehovah der Heerscharen mich gesendet hat. Lobsinge und sei fröhlich, du Tochter Zijon; denn siehe, Ich komme und wohne in deiner Mitte, spricht Jehovah. Und viele Völkerschaften werden an jenem Tage Jehovah anhangen und Mein Volk werden; und Ich werde in deiner Mitte wohnen, auf daß du erkennst, daß Jehovah der Heerscharen mich zu dir gesendet hat. Und Jehovah erbet den Jehudah als sein Teil auf dem Boden der Heiligkeit und erwählt noch Jerusalem. Stille sei alles Fleisch vor dem Angesichte Jehovahs; denn Er ist aufgewacht aus der Wohnstätte Seiner Heiligkeit.',
    },
    3: {
        1: 'Und Er ließ mich Jehoschua, den Hohenpriester sehen, wie er vor dem Engel Jehovahs stand, und den Satan, der ihm zur Rechten stand, ihm zu widerstehen.',
        2: 'Und Jehovah sprach zum Satan: Jehovah bedrohe dich, Satan, ja, Jehovah bedrohe dich, Der Jerusalem erwählt hat. Ist dieser nicht ein Brand, aus dem Feuer entrissen?',
        3: 'Und Jehoschua war angetan mit schmutzigen Kleidern, und er stand vor dem Engel.',
        4: 'Und er hob an und sprach zu denen, die vor ihm standen, sprechend: Nehmt weg von ihm die schmutzigen Kleider; und sprach zu ihm: Siehe, Ich habe die Missetat von dir vorbeigehen lassen und dich bekleidet mit Feierkleidern.',
        5: 'Und Er sprach: setzet ihm einen reinen Kopfbund auf sein Haupt. Und sie setzten ihm einen reinen Kopfbund auf sein Haupt und zogen ihm Kleider an, und der Engel Jehovahs stand da.',
        6: 'Und es bezeugte der Engel Jehovahs den Jehoschua und sprach:',
        7: 'So spricht Jehovah der Heerscharen: Wenn du in Meinen Wegen wandelst und wenn du Meiner Hut wartest, so sollst du auch Meinem Hause Recht sprechen und auch Meine Vorhöfe hüten, und Ich gebe dir Gänge zwischen den hier Stehenden.',
        8: 'So höre denn, Jehoschua, Hoherpriester, du und deine Genossen, die vor dir sitzen, da sie Männer sind des Wahrzeichens: denn siehe, Ich lasse kommen Meinen Knecht, den Sproß.',
        9: 'Denn siehe den Stein, den Ich vor Jehoschua legte, auf dem einen Stein sind sieben Augen. Siehe, Ich grabe selbst seine Eingrabung hinein, spricht Jehovah der Heerscharen, und lasse weichen die Missetat dieses Landes an einem Tag.',
        10: 'An jenem Tage, spricht Jehovah der Heerscharen, werdet ihr, jeder Mann seinem Genossen rufen unter den Weinstock und unter den Feigenbaum.',
    },
    4: {
        1: 'Und der Engel, der mit mir geredet, kehrte zurück und weckte mich auf wie einen Mann, der aus seinem Schlafe aufgeweckt wird.',
        2: 'Und er sagte zu mir: Was siehst du? Und ich sagte: Ich sehe, und siehe, ein Leuchter, ganz von Gold, und sein Ölbehälter oben auf, und seine sieben Lampen darauf; sieben und sieben Gießröhren für die Lampen, die oben waren.',
        3: 'Und zwei Ölbäume dabei, einer zur Rechten des Ölbehälters und einer zu seiner Linken.',
        4: 'Und ich hob an und sprach zu dem Engel, der mit mir redete, und sprach: Was sind diese, mein Herr?',
        5: 'Und der Engel, der mit mir redete, antwortete und sprach zu mir: Weißt du nicht, was diese sind? Und ich sagte: Nein, mein Herr.',
        6: 'Und er antwortete und sprach zu mir, sprechend: Dies Wort Jehovahs ist an Serubbabel, sprechend: Nicht durch Vermögen und nicht durch Kraft, sondern durch Meinen Geist, spricht Jehovah der Heerscharen.',
        7: 'Wer bist du, großer Berg? Vor Serubbabel wirst du eine Ebene, daß er herausbringe den Hauptstein mit dem Getöse: Gnade, Gnade ihm.',
        8: 'Und es geschah Jehovahs Wort an mich, sprechend:',
        9: 'Die Hände Serubbabels gründeten dies Haus und seine Hände führen es aus. Und du sollst erkennen, daß Jehovah der Heerscharen mich zu euch gesendet hat.',
        10: 'Denn wer will den Tag der kleinen Dinge verachten? Und sie sind fröhlich und sehen das Senkblei in Serubbabels Hand. Sieben sind diese, die Augen Jehovahs, sie durchstreifen die ganze Erde.',
        11: 'Und ich antwortete und sprach zu ihm: Was sollen diese zwei Ölbäume zur Rechten des Leuchters und zu seiner Linken?',
        12: 'Und ich hob zum zweitenmal an und sprach zu ihm: Was sind die zwei Beeren der Ölbäume, die zur Seite der zwei goldenen Röhren sind und aus sich das Gold leeren?',
        13: 'Und Er sprach zu mir, sprechend: Weißt du nicht, was diese sind? Und ich sprach: Nein, mein Herr.',
        14: 'Und Er sprach: Dies sind die zwei Söhne des Ölbaums, die bei dem Herrn der ganzen Erde stehen.',
    },
    5: {
        1: 'Und ich wandte mich zurück und hob meine Augen auf und sah, und siehe, eine fliegende Schriftrolle.',
        2: 'Und Er sprach zu mir: Was siehst du? Und ich sprach: Ich sehe eine fliegende Schriftrolle. Ihre Länge ist zwanzig Ellen und ihre Breite zehn Ellen.',
        3: 'Und Er sprach zu mir: Dies ist die Verwünschung, die ausgeht über die Angesichte des ganzen Landes: denn jeder, der da stiehlt, ist danach unschuldig wie sie, und jeder, der danach schwört, ist unschuldig wie sie.',
        4: 'Ich habe sie ausgehen lassen, spricht Jehovah der Heerscharen, daß sie eingehen soll in das Haus des Diebes und in das Haus dessen, der in Meinem Namen schwört zur Lüge, und sie soll herbergen inmitten seines Hauses, und auffressen dasselbe und sein Holz und seine Steine.',
        5: 'Und der Engel, der mit mir redete, ging heraus und sprach zu mir: Hebe doch deine Augen auf, und siehe was da herausgeht.',
        6: 'Und ich sprach: Was ist das? und er sprach: Das ist das Ephah, das herauskommt. Und er sprach: Dies ist ihr Anblick im ganzen Land.',
        7: 'Und siehe, ein Zentner Blei ward aufgehoben, und dieses eine Weib, das inmitten des Ephahs sitzt.',
        8: 'Und er sprach: Dies ist die Ungerechtigkeit! und warf sie mitten in das Ephah, und warf das Bleigewicht auf seine Mündung.',
        9: 'Und ich hob meine Augen und sah, und siehe, zwei Weiber kamen hervor und Wind war in ihren Flügeln, und sie hatten zwei Flügel wie Flügel des Storches, und hoben das Ephah auf zwischen Erde und Himmel.',
        10: 'Und ich sprach zu dem Engel, der mit mir redete: Wohin bringen sie das Ephah?',
        11: 'Und er sprach zu mir: Um ihm ein Haus zu bauen im Lande Schinear. Und dort wird es gefestigt und in seiner Stätte niedergelassen werden.',
    },
    6: {
        1: 'Und ich wandte mich zurück und hob meine Augen auf und sah, und siehe, vier Streitwagen kamen zwischen den zwei Bergen hervor, und die Berge waren Berge von Erz.',
        2: 'Am ersten Streitwagen waren rote Rosse und am zweiten Streitwagen schwarze Rosse.',
        3: 'Und am dritten Streitwagen weiße Rosse und am vierten Streitwagen getüpfelte starke Rosse.',
        4: 'Und ich hob an und sprach zu dem Engel, der mit mir redete: Was sollen diese, mein Herr?',
        5: 'Und der Engel antwortete und sprach zu mir: Dies sind die vier Winde der Himmel, die ausgehen, nachdem sie bei dem Herrn der ganzen Erde gestanden haben.',
        6: 'Der, an dem die Schwarzen Pferde sind, zieht aus in das Land der Mitternacht, und die weißen ziehen hinter ihnen aus, und die getüpfelten ziehen in das Land des Südens.',
        7: 'Und die starken zogen aus und suchten zu gehen, um die Erde zu durchwandeln. Und er sprach: Gehet hin, durchwandelt die Erde, und sie durchwandelten die Erde.',
        8: 'Und er schrie mir zu und redete zu mir, sprechend: Siehe, die ausziehen in das Land der Mitternacht, die lassen Meinen Geist ruhen im Land der Mitternacht.',
        9: 'Und es geschah an mich das Wort Jehovahs, sprechend:',
        10: 'Man nehme von den Weggeführten, von Cheldai, von Tobjahn und von Jedajah; und du sollst hineingehen an jenem Tag, und du sollst hineingehen in das Haus Joschijahs, des Sohnes Zephanjahs, die von Babel kommen,',
        11: 'Und du sollst Silber und Gold nehmen und sollst Kronen machen; und sollst eine setzen auf das Haupt Jehoschuas, des Sohnes Jehozadaks, des Hohenpriesters,',
        12: 'Und sprechen sollst du zu ihm, sprechend: So spricht Jehovah der Heerscharen, sprechend: Siehe, ein Mann, Zemach ist sein Name, und es wird sprossen unter ihm, und er wird Jehovahs Tempel bauen.',
        13: 'Und er wird Jehovahs Tempel bauen und wird Majestät tragen, und sitzen und herrschen auf seinem Thron, und er wird Priester sein auf seinem Thron, und ein Rat des Friedens wird zwischen beiden sein.',
        14: 'Und die Kronen sollen für Chelem und Tobijah und Jedajah und Chen, Zephanjahs Sohn, als Angedenken in Jehovahs Tempel sein.',
        15: 'Und die von ferne werden kommen, und im Tempel Jehovahs bauen, und ihr sollt wissen, daß Jehovah der Heerscharen mich an euch gesendet hat. Und das wird geschehen, wenn ihr hört auf die Stimme Jehovahs, eures Gottes.',
    },
    7: {
        1: 'Und es geschah im vierten Jahr des Königs Darius, daß das Wort Jehovahs geschah an Sacharjah am vierten des neunten Monats Chislev;',
        2: 'Und Bethel sandte Scharezer und RegemMelech und seine Leute, das Angesicht Jehovahs anzuflehen;',
        3: 'Und zu sprechen zu den Priestern in dem Haus Jehovahs der Heerscharen und zu den Propheten, sprechend: Soll ich im fünften Monat weinen, und mich enthalten, wie ich nun etliche Jahre her getan?',
        4: 'Und es geschah das Wort Jehovahs der Heerscharen an mich, sprechend:',
        5: 'Sprich zu dem ganzen Volk des Landes und zu den Priestern, sprechend: Wenn ihr gefastet und geklagt habt im fünften und im siebenten diese siebzig Jahre her, habt ihr denn wirklich für mich gefastet?',
        6: 'Und wenn ihr aßet und wenn ihr tranket, wart nicht ihr es, die da aßen, und ihr, die da tranken?',
        7: 'Sind das nicht die Worte, die Jehovah durch die Hand der früheren Propheten ausrufen ließ, da Jerusalem bewohnt und behaglich war, und seine Städte ringsumher, und man noch im Mittagland und in der Niederung wohnte?',
        8: 'Und es geschah Jehovahs Wort zu Sacharjah, sprechend:',
        9: 'So spricht Jehovah der Heerscharen, sprechend: Richtet ein Gericht der Wahrheit und tut Barmherzigkeit und Erbarmen, jeder Mann mit seinem Bruder.',
        10: 'Und drückt nicht die Witwe und die Waise, den Fremdling und den Elenden, und denkt in eurem Herzen nicht Böses, der Mann wider seinen Bruder.',
        11: 'Sie aber weigerten sich, darauf zu merken, und kehrten abtrünnig die Schulter zu, und machten ihre Ohren schwer, daß sie nicht hörten.',
        12: 'Und ihr Herz machten sie zu einem Diamant, daß sie nicht hörten auf das Gesetz und auf die Worte, die Jehovah der Heerscharen in Seinem Geist sandte durch die Hand der früheren Propheten, und groß war die Entrüstung von Jehovah der Heerscharen.',
        13: 'Und so geschah, wie Er rief, und sie hörten nicht, so sollen sie rufen und Ich werde nicht hören, spricht Jehovah der Heerscharen.',
        14: 'Und Ich zerstürmte sie über alle Völkerschaften, die sie nicht kannten, und das Land war verwüstet hinter ihnen, daß niemand hindurchging, noch zurückkehrte, und sie setzten das Land der Begehr in Verwüstung.',
    },
    8: {
        1: 'Und es geschah das Wort Jehovahs der Heerscharen, sprechend:',
        2: 'So spricht Jehovah der Heerscharen: Mit großem Eifer habe Ich für Zijon geeifert, und geeifert mit großem Grimm für dasselbe.',
        3: 'So spricht Jehovah: Ich kehre zurück auf Zijon, und wohne inmitten Jerusalems. Und nennen wird man Jerusalem die Stadt der Wahrheit, und den Berg Jehovahs der Heerscharen den Berg der Heiligkeit.',
        4: 'So spricht Jehovah der Heerscharen: Wohnen werden noch Greise und Greisinnen in den Straßen Jerusalems, und der Mann mit seiner Stütze in seiner Hand, vor der Menge der Tage.',
        5: 'Und die Straßen der Stadt sollen voll sein von Knaben und Mädchen, die auf ihren Straßen spielen.',
        6: 'So spricht Jehovah der Heerscharen: Ja, wunderbar wird es in den Augen des Überrestes dieses Volkes sein in jenen Tagen. Wird es auch wunderbar in Meinen Augen sein? spricht Jehovah der Heerscharen.',
        7: 'So spricht Jehovah der Heerscharen: Siehe, Ich rette Mein Volk aus dem Lande des Aufgangs und aus dem Lande des Untergangs der Sonne;',
        8: 'Und Ich will sie hereinbringen, daß sie wohnen in Jerusalems Mitte, und sie Mein Volk seien und Ich ihr Gott in Wahrheit und in Gerechtigkeit.',
        9: 'So spricht Jehovah der Heerscharen: Stärket eure Hände, ihr, die in diesen Tagen hört diese Worte aus dem Munde der Propheten, die da sind an dem Tage, da man den Grund zum Hause Jehovahs der Heerscharen legte, den Tempel aufzubauen.',
        10: 'Denn vor selbigen Tagen war kein Lohn für den Menschen, und war kein Lohn für das Vieh; und der, so da ausging, und der einging, hatte keinen Frieden von dem Dränger, und Ich entsandte alle Menschen, den Mann wider seinen Genossen.',
        11: 'Nun aber bin Ich nicht wie in früheren Tagen gegen den Überrest von diesem Volke, spricht Jehovah der Heerscharen.',
        12: 'Sondern sie sollen des Friedens Same sein, der Weinstock wird seine Frucht geben, und die Erde wird geben ihr Gewächs, und die Himmel geben ihren Tau. Und Ich will alles dies dem Überrest dieses Volkes zum Erbe geben.',
        13: 'Und wird geschehen, wie ihr ein Fluch unter den Völkerschaften wart, Haus Jehudah und Haus Israel, so will Ich euch retten, daß ihr ein Segen werdet. Fürchtet euch nicht, stärkt eure Hände.',
        14: 'Denn so spricht Jehovah der Heerscharen: Gleichwie Ich sann, euch Übles anzutun, weil eure Väter Mich entrüstet, spricht Jehovah der Heerscharen, und Mich nicht reuete:',
        15: 'So will Ich zurückkehren, will in diesen Tagen sinnen, Jerusalem und dem Haus Jehudah Gutes zu tun. - Fürchtet euch nicht!',
        16: 'Dies sind die Dinge, die ihr tun sollt: Redet Wahrheit, der Mann mit seinem Genossen; die Wahrheit und das Gericht des Friedens richtet in euren Toren!',
        17: 'Denkt nicht in eurem Herzen Böses, der Mann wider seinen Genossen; und liebt nicht den Schwur der Lüge; denn solches alles hasse Ich, spricht Jehovah.',
        18: 'Und es geschah das Wort Jehovahs der Heerscharen zu mir, sprechend:',
        19: 'So spricht Jehovah der Heerscharen: Das Fasten des vierten und das Fasten des fünften und das Fasten des siebenten und das Fasten des zehnten wird dem Hause Jehudah zur Freude und zur Fröhlichkeit und zu guten Festzeiten werden. Und die Wahrheit und den Frieden sollt ihr lieben.',
        20: 'So spricht Jehovah der Heerscharen: Es werden noch Völker kommen und Bewohner vieler Städte;',
        21: 'Und werden gehen die Bewohner der einen zu der anderen, sprechend: Laßt uns gehen, um anzuflehen das Angesicht Jehovahs und zu suchen Jehovah der Heerscharen. Auch ich will gehen!',
        22: 'Und viele Völker und zahlreiche Völkerschaften werden kommen, Jehovah der Heerscharen zu suchen in Jerusalem, und anzuflehen das Angesicht Jehovahs.',
        23: 'So spricht Jehovah der Heerscharen: In jenen Tagen werden anfassen zehn Männer aus allen Zungen der Völkerschaften, und sie werden anfassen den Rockflügel eines jüdischen Mannes, sprechend: Wir wollen mit euch gehen; denn wir hören, daß Gott mit euch ist.',
    },
    9: {
        1: 'Weissagung. Das Wort Jehovahs über das Land Chadrach, und Damask, Seinen Ruheplatz; denn auf Jehovah ist das Auge des Menschen und aller Stämme Israels.',
        2: 'Und auch über Chamath, das daran grenzt, Zor und Zidon; denn es war sehr weise.',
        3: 'Und Zor baute sich ein Bollwerk, und häufte Silber wie Staub auf und pures Gold wie den Kot der Gassen.',
        4: 'Siehe, arm wird es der Herr machen, und sein Vermögen stürzen in das Meer, und es selber soll vom Feuer gefressen werden.',
        5: 'Aschkelon sieht es und fürchtet sich, und Gazah, und ist sehr erschüttert, und Ekron; denn er schämt sich seines Verlasses, und der König von Gazah vergeht, und Aschkelon wird nicht bewohnt.',
        6: 'Und der Bastard wird in Aschdod wohnen, und der Philister Stolz rotte Ich aus.',
        7: 'Und Ich will wegnehmen sein Blut aus seinem Munde, und seine Scheusale zwischen seinen Zähnen heraus. Und auch er verbleibt unserem Gott, und wird sein wie ein Stammhaupt in Jehudah, und Ekron wie der Jebusiter.',
        8: 'Und Ich beziehe ein Heerlager für Mein Haus, wegen des Heeres, das vorüberzieht und zurückkehrt, daß kein Fronvogt mehr es durchziehe; denn jetzt habe Ich es angesehen mit Meinen Augen.',
        9: 'Frohlocke sehr, Tochter Zijons, rufe laut, Tochter Jerusalems. Siehe, dein König kommt zu dir. Ein Gerechter und Geretteter ist Er, demütig, und reitet auf einem Esel, und auf einem Füllen, dem Sohn der Eselinnen.',
        10: 'Und Ich rotte aus den Streitwagen aus Ephraim und das Roß aus Jerusalem, und ausgerottet wird des Streites Bogen, und Er wird Frieden reden zu den Völkerschaften; und Seine Herrschaft wird sein von Meer zu Meer und von dem Flusse bis an das Äußerste der Erde.',
        11: 'Auch dir entsende Ich durch deines Bundes Blut die Gebundenen aus der Grube, worin kein Wasser ist.',
        12: 'Kehrt zurück zur Feste, ihr Gebundenen der Hoffnung, auch heute sage Ich an, Ich will dir doppelt zurückgeben.',
        13: 'Denn Jehudah habe Ich Mir gespannt, und Ephraim erfüllt mit dem Bogen, und deine Söhne, Zijon, auferweckt mit deinen Söhnen, Javan, und will dich setzen zu einem Schwert des Helden.',
        14: 'Und über ihnen wird erscheinen Jehovah, und wie der Blitz geht aus Sein Pfeil, und der Herr Jehovah stößt in die Posaune, und geht dahin in des Südens Wetter.',
        15: 'Jehovah der Heerscharen schirmt über sie, und sie fressen auf, und sie zerstampfen die Steine der Schleuder, und sie trinken, sie toben wie vom Wein. Und voll sind sie wie das Sprengbecken, wie die Ecksäulen des Altars.',
        16: 'Und retten wird sie an jenem Tag Jehovah, ihr Gott, Sein Volk wie eine Herde; denn Steine des Diadems sind sie, die auf Seinem Boden emporragen.',
        17: 'Denn wie groß ist Seine Güte, und wie groß Seine Schöne. Korn läßt Jünglinge und Most Jungfrauen heranwachsen.',
    },
    10: {
        1: 'Bittet von Jehovah Regen zur Zeit des Spätregens, Jehovah, Der Gewölke macht, so gibt Er ihnen Regen in Güssen, jedem Mann Kraut im Felde.',
        2: 'Denn Unrecht reden die Theraphim und die Wahrsager schauen Lüge, und Eitles reden die Träume, nichtig trösten sie. Darum ziehen sie aus wie Schafe, sie werden gedrückt, weil kein Hirte da ist.',
        3: 'Über die Hirten ist Mein Zorn entbrannt, und an den Böcken suche Ich heim; denn Jehovah der Heerscharen sucht heim Seine Herde, das Haus Jehudahs, und macht sie zum Rosse Seiner Majestät im Streite.',
        4: 'Aus Ihm ist der Eckstein, aus Ihm der Pflock, aus Ihm der Bogen des Streites, aus Ihm geht hervor jeder Treiber zumal.',
        5: 'Und werden sein wie die Helden, zertretend in den Kot der Gassen im Streite, und sie werden streiten, denn Jehovah ist mit ihnen, und beschämt werden, die reiten auf Rossen.',
        6: 'Und mächtig mache Ich das Haus Jehudah, und das Haus Josephs rette Ich, und laß sie wohnen. Denn ihrer erbarme Ich Mich. Und sie sollen sein, als hätte Ich sie nicht verworfen; denn Ich, Jehovah, bin ihr Gott, und antworte ihnen.',
        7: 'Und wie ein Held soll sein Ephraim, und ihr Herz wird fröhlich wie vom Wein, und ihre Söhne werden es sehen und fröhlich sein; und in Jehovah wird ihr Herz frohlocken.',
        8: 'Ich locke sie und bringe sie zusammen, denn Ich löse sie ein, daß sie sich mehren, wie sie sich gemehrt hatten.',
        9: 'Und Ich säe sie unter die Völker, und in den Fernen gedenken sie Meiner, und sie leben mit ihren Söhnen und kehren zurück.',
        10: 'Und Ich bringe sie zurück aus dem Lande Ägypten, und bringe sie aus Aschur zusammen, und bringe sie hinein in das Land Gilead und zum Libanon, und wird nicht genug für sie gefunden.',
        11: 'Und Er zieht durch das Meer der Drangsal, und schlägt im Meere die Wogen, und werden austrocknen all die Schlünde des Stromes; und hinabgebracht wird Aschurs Stolz, und das Zepter Ägyptens wird weggenommen.',
        12: 'Und mächtig mache Ich sie in Jehovah, daß sie in Seinem Namen wandeln, spricht Jehovah.',
    },
    11: {
        1: 'Öffne deine Türen, Libanon, daß Feuer deine Zedern auffresse.',
        2: 'Heule, Tanne, daß die Zeder ist gefallen, daß die Stattlichen verheert sind. Heult, ihr Eichen Baschans, daß der Wald Bazar herabgestürzt ist.',
        3: 'Die Stimme des Geheuls der Hirten, daß verheert ist ihr Prunk! Die Stimme des Brüllens der jungen Löwen, denn der Stolz des Jordan ist verheert.',
        4: 'So spricht Jehovah, mein Gott: Weide die Herde, die erwürgt wird;',
        5: 'Die ihre Besitzer erwürgen und es für keine Schuld halten, und die, so sie verkaufen, sprechen: Gesegnet sei Jehovah, daß ich reich werde; und ihre Hirten bemitleiden sie nicht.',
        6: 'Nicht mehr werde Ich bemitleiden die Bewohner des Landes, spricht Jehovah, und siehe, Ich überantworte die Menschen, jeden Mann in die Hand seines Genossen, und in die Hand seines Königs, daß sie das Land zerstoßen, und Ich errette nicht aus ihrer Hand.',
        7: 'Und ich weidete die Herde, die erwürgt wird, deshalb die Elenden der Herde, und nahm mir zwei Stöcke, den einen nannte ich Noam und den anderen nannte ich Choblim, und Ich weidete die Herde.',
        8: 'Und ich schaffte die drei Hirten weg in einem Monat, und meine Seele ward ungeduldig ob ihnen, und auch ihre Seele ward meiner überdrüssig.',
        9: 'Und ich sprach: Ich mag euch nicht weiden. Wer sterben will, der sterbe, wer weggeschafft werden soll, der werde weggeschafft, und von dem Überrest esse das eine das Fleisch des anderen.',
        10: 'Und ich nahm meinen Stock Noam und zerhieb ihn, um zunichte zu machen meinen Bund, den ich mit allen Völkern schloß.',
        11: 'Und er ward zunichte an jenem Tag, und so erkannten die Elenden der Herde, die auf mich hielten, daß es das Wort Jehovahs war.',
        12: 'Und ich sprach zu ihnen: Wenn es gut ist in euren Augen, gebt mir meinen Lohn, wo nicht, so unterlasset es. Und sie wogen mir meinen Lohn, dreißig Silberlinge.',
        13: 'Und Jehovah sprach zu mir: Wirf dem Töpfer hin den vortrefflichen Wert, zu dem Ich von ihnen geschätzt ward. Und ich nahm die dreißig Silberlinge, und warf sie in Jehovahs Haus dem Töpfer hin.',
        14: 'Und ich zerhieb meinen zweiten Stock Choblim, um zunichte zu machen die Brüderschaft zwischen Jehudah und Israel.',
        15: 'Und Jehovah sprach zu mir: Nimm dir noch das Gerät eines närrischen Hirten.',
        16: 'Denn siehe, Ich lasse aufstehen einen Hirten in dem Land, der das Verschollene nicht heimsucht, das Junge nicht sucht, und das Zerbrochene nicht heilt, das Stehende nicht versorgt, das Fleisch des Gemästeten aber aufißt und seine Klauen abreißt.',
        17: 'Wehe dem nichtsnutzigen Hirten, der die Herde verläßt; das Schwert über seinen Arm, und über sein rechtes Auge! Sein Arm verdorre und sein rechtes Auge werde trübe!',
    },
    12: {
        1: 'Weissagung. Das Wort Jehovahs über Israel. Es spricht Jehovah, Der die Himmel ausspannt und die Erde gründet, und den Geist des Menschen in seinem Inneren bildet.',
        2: 'Siehe, Ich mache Jerusalem zum Taumelbecken für alle Völker ringsumher, und auch für Jehudah wird sie es sein bei der Belagerung wider Jerusalem.',
        3: 'Und es geschieht am selben Tag, daß Ich Jerusalem zum Laststein mache allen Völkern; alle, die daran aufladen, werden sich daran zerschneiden, und alle Völkerschaften der Erde werden sich versammeln wider dasselbe.',
        4: 'An selbigem Tage, spricht Jehovah, schlage Ich mit Stumpfsinn jeglich Roß, und mit Wahnsinn den, der darauf reitet, und über das Haus Jehudah tue Ich Meine Augen auf, und jeglich Roß der Völker werde Ich mit Blindheit schlagen.',
        5: 'Und Jehudahs Stammhäupter werden in ihrem Herzen sprechen: Mächtig mache ich mir Jerusalems Bewohner durch Jehovah der Heerscharen, ihren Gott.',
        6: 'An jenem Tage werde Ich die Stammhäupter Jehudahs machen wie ein Feuerbecken unter Holzstücken und wie eine Feuerfackel in der Garbe, daß sie zur Rechten und zur Linken alle Völker ringsumher auffressen, und wohnen wird noch Jerusalem an seine Stelle in Jerusalem.',
        7: 'Und Jehudahs Zelte wird Jehovah zuerst retten, daß nicht der Ruhm des Hauses David und der Ruhm von Jerusalems Bewohnern groß tue wider Jehudah.',
        8: 'An jenem Tage wird Jehovah schirmen den Bewohner Jerusalems, daß, wer da strauchelt unter ihnen, wird sein an jenem Tage wie David, und das Haus Davids wird sein wie Gott, wie Jehovahs Engel vor ihrem Angesicht.',
        9: 'Und an selbigem Tage wird geschehen, daß Ich suche alle Völkerschaften zu vernichten, die wider Jerusalem kommen.',
        10: 'Und Ich gieße aus über Davids Haus und über den Bewohner Jerusalems den Geist der Gnade und des Flehens, und sie werden zu Mir aufblicken, Den sie durchstochen haben, und klagen um Ihn, wie man klagt um den Einzigen, und bitterlich weinen um Ihn, wie man bitterlich weint um den Erstgeborenen.',
        11: 'An jenem Tag wird die Klage groß sein in Jerusalem, wie die Klage bei Hadadrimmon in der Talebene Megiddo.',
        12: 'Und klagen wird das Land, Familien um Familien besonders, die Familie des Hauses David besonders und ihre Weiber besonders, die Familie des Hauses Nathan besonders und ihre Weiber besonders;',
        13: 'Die Familie des Hauses Levi besonders und ihre Weiber besonders; die Familie Schimei besonders und ihre Weiber besonders.',
        14: 'Alle Familien, die verblieben sind, Familien um Familien besonders und ihre Weiber besonders.',
    },
    13: {
        1: 'An jenem Tage wird dem Hause Davids und Jerusalems Bewohner ein Born geöffnet werden wider die Sünde und wider die Beflekkung.',
        2: 'Und es geschieht an jenem Tag, spricht Jehovah der Heerscharen, daß Ich die Namen der Götzenbilder aus dem Land ausrotten werde, daß man ihrer nicht mehr gedenkt; und auch die Propheten und den unreinen Geist will Ich dahingehen lassen aus dem Lande;',
        3: 'Und wird geschehen, daß, so ein Mann noch weissagt, sein Vater und seine Mutter, die ihn gezeugt, zu ihm sprechen: Du sollst nicht leben; denn Lüge redest du im Namen Jehovahs; und werden ihn durchstechen, sein Vater und seine Mutter, die ihn gezeugt, ob seinem Weissagen.',
        4: 'Und wird an jenem Tag geschehen, daß die Propheten sich schämen, ein jeder Mann ob seinem Gesicht, wenn er weissagt, und nicht mehr den härenen Mantel anziehen, um zu täuschen.',
        5: 'Und er wird sagen: Ich bin kein Prophet, ich bin ein Mann, der den Boden baut, denn mich hatte ein Mensch verkauft in meiner Jugend.',
        6: 'Und sagt man zu ihm: Was sind das für Schläge zwischen deinen Händen?, so wird er sagen: Die schlug man mir im Hause derer, die mich lieben.',
        7: 'Auf, Schwert, wache auf wider Meinen Hirten und wider den Mann Meiner Gemeinschaft! spricht Jehovah der Heerscharen; schlage den Hirten, daß die Herde sich zerstreue, so will Ich Meine Hand zu den Geringen zurückwenden.',
        8: 'Und soll im ganzen Land geschehen, spricht Jehovah, daß je zwei Teile darin ausgerottet werden, daß sie verscheiden, und das Drittel darin übrigbleibe.',
        9: 'Und das Drittel will Ich ins Feuer hineinbringen und will sie läutern, wie man Silber läutert, und will sie prüfen, wie man prüft das Gold. Es ruft Meinen Namen an, und Ich antworte ihm, Ich spreche: Mein Volk ist es; und es spricht: Jehovah, mein Gott!',
    },
    14: {
        1: 'Siehe, ein Tag kommt dem Jehovah, da man die Beute teilt in deiner Mitte.',
        2: 'Und Ich versammle alle Völkerschaften nach Jerusalem zum Streit, und die Stadt wird erobert und die Häuser werden geplündert und die Weiber geschändet, und die Hälfte der Stadt zieht in die Verbannung hinaus, aber das übrige des Volkes wird nicht ausgerottet aus der Stadt.',
        3: 'Und wider diese Völkerschaften wird ausziehen Jehovah und streiten, wie am Tage, da Er stritt am Tage des Kampfes.',
        4: 'Und Seine Füße werden an jenem Tag auf dem Berg der Ölbäume stehen, der vor Jerusalem gen Osten ist. Und der Berg der Ölbäume wird sich spalten in seine Hälfte gen Aufgang und zum Meere hin in eine sehr große Schlucht, und eine Hälfte des Berges weicht hin gen Mitternacht, und seine Hälfte gen Mittag.',
        5: 'Und ihr werdet fliehen durch die Schlucht Meiner Berge; denn die Schlucht der Berge wird reichen bis Azal; und ihr flieht, wie ihr geflohen seid vor dem Erdbeben in den Tage Ussijahs, des Königs von Jehudah, und es kommt Jehovah, mein Gott; all Seine Heiligen mit Dir.',
        6: 'Und es geschieht an jenem Tage: kein Licht wird sein, nur Kälte und Frost.',
        7: 'Und es wird ein Tag sein, - dem Jehovah ist er bekannt - nicht Tag und nicht Nacht, und zur Zeit des Abends wird Licht werden.',
        8: 'Und es geschieht an jenem Tag, daß lebendige Wasser ausgehen von Jerusalem, zur Hälfte nach dem vorderen Meere und zur Hälfte nach dem hinteren Meer. Im Sommer und im Winter wird es sein.',
        9: 'Und König wird Jehovah sein über die ganze Erde. An jenem Tage wird Jehovah einer sein, und Sein Name einer.',
        10: 'Das ganze Land wird ringsum sein wie das Gefilde von Geba bis nach Rimmon, mittäglich von Jerusalem, und es wird erhöht sein und bewohnt sein an seiner Stelle, vom Tore Benjamins bis zum Orte des ersten Tores bis zum Tore der Ecken und dem Turm Chananeels bis zu den Kelterkufen des Königs.',
        11: 'Und sie werden darin wohnen, und kein Bann wird mehr sein, und man wohnt in Jerusalem in Sicherheit.',
        12: 'Dies aber wird die Plage sein, womit Jehovah plagt alle Völker, die wider Jerusalem ausrücken: sein Fleisch schwindet dahin, da er noch auf seinen Füßen steht, und seine Augen schwinden dahin in ihren Höhlen, und seine Zunge schwindet dahin in ihrem Munde.',
        13: 'Und an jenem Tage wird geschehen, daß viel Toben von Jehovah unter ihnen sein wird: und der Mann wird die Hand seines Genossen erfassen, und seine Hand steigt auf über die Hand seines Genossen.',
        14: 'Und auch Jehudah wird wider Jerusalem streiten; und gesammelt wird das Vermögen aller Völkerschaften ringsumher, sehr viel Gold und Silber und Kleider.',
        15: 'Und ebenso wird sein die Plage des Rosses, des Maultiers, des Kamels und des Esels, und alles Viehs, das in jenen Heerlagern ist, wie diese Plage.',
        16: 'Und wird geschehen, daß alle von allen Völkerschaften, die übrigblieben, die wider Jerusalem gekommen waren, heraufziehen werden von Jahr zu Jahr, um anzubeten den König Jehovah der Heerscharen, und das Fest der Laubhütten zu feiern.',
        17: 'Und es soll geschehen, wer von den Familien der Erde nicht heraufzieht nach Jerusalem, um den König Jehovah der Heerscharen anzubeten, auf ihnen wird kein Regen sein.',
        18: 'Und wenn die Familie Ägypten nicht heraufzieht, und nicht kommt, und nicht mit ihnen ist, so wird sein die Plage, womit Jehovah die Völkerschaften schlägt, die nicht heraufzogen, das Fest der Laubhütten zu feiern.',
        19: 'Das wird die Sünde Ägyptens sein, und die Sünde all der Völkerschaften, die nicht heraufzogen, das Fest der Laubhütten zu feiern.',
        20: 'An jenem Tage wird sein auf den Glöckchen der Rosse: Heiligkeit dem Jehovah! Und die Töpfe werden sein im Haus Jehovahs wie die Sprengbecken vor dem Altar.',
        21: 'Und jeder Topf in Jerusalem und in Jehudah wird Heiligkeit sein dem Jehovah der Heerscharen; und alle, die opfern, werden kommen und davon nehmen und darin kochen, und wird kein Kanaaniter mehr im Hause Jehovahs der Heerscharen sein an jenem Tage.',
    },
}
